package com.datacleaning.app.service;

import com.fasterxml.jackson.core.type.TypeReference;
import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.dataformat.csv.CsvMapper;
import com.fasterxml.jackson.dataformat.csv.CsvSchema;
import org.apache.poi.ss.usermodel.*;
import org.springframework.stereotype.Service;
import org.springframework.web.multipart.MultipartFile;
import java.io.*; import java.nio.charset.StandardCharsets; import java.util.*;

@Service
public class DataService {
  private final ObjectMapper mapper; private final Map<String,List<Map<String,Object>>> sessions=new java.util.concurrent.ConcurrentHashMap<>();
  private static final Set<String> NULLS=Set.of("", "null", "none", "nan", "n/a", "na", "-", "--", "---");
  public DataService(ObjectMapper mapper){this.mapper=mapper;}
  public List<Map<String,Object>> parse(MultipartFile file) throws IOException {
    String name=Objects.requireNonNullElse(file.getOriginalFilename(),"data.csv").toLowerCase(Locale.ROOT); byte[] bytes=file.getBytes();
    if(bytes.length>50*1024*1024) throw new IllegalArgumentException("File exceeds the 50 MB limit.");
    if(name.endsWith(".csv")) { CsvMapper csv=new CsvMapper(); CsvSchema schema=CsvSchema.emptySchema().withHeader(); MappingIterator<Map<String,Object>> it=csv.readerFor(Map.class).with(schema).readValues(new String(bytes,StandardCharsets.UTF_8)); return it.readAll(); }
    if(name.endsWith(".json")) { JsonNode n=mapper.readTree(bytes); if(n.isArray()) return mapper.convertValue(n,new TypeReference<List<Map<String,Object>>>(){}); if(n.isObject()) return List.of(mapper.convertValue(n,new TypeReference<Map<String,Object>>(){})); throw new IllegalArgumentException("JSON must contain an object or an array of objects."); }
    if(name.endsWith(".xlsx")||name.endsWith(".xls")) { try(Workbook wb=WorkbookFactory.create(new ByteArrayInputStream(bytes))) { Sheet s=wb.getSheetAt(0); if(s.getPhysicalNumberOfRows()==0)return new ArrayList<>(); DataFormatter fmt=new DataFormatter(); Row hr=s.getRow(0); List<String> headers=new ArrayList<>(); for(Cell c:hr)headers.add(fmt.formatCellValue(c)); List<Map<String,Object>> out=new ArrayList<>(); for(int i=1;i<=s.getLastRowNum();i++){Row r=s.getRow(i);if(r==null)continue;Map<String,Object> m=new LinkedHashMap<>();for(int j=0;j<headers.size();j++)m.put(headers.get(j),r.getCell(j)==null?"":fmt.formatCellValue(r.getCell(j)));out.add(m);}return out;} }
    throw new IllegalArgumentException("Unsupported file type. Upload CSV, JSON, XLS or XLSX.");
  }
  public String createSession(List<Map<String,Object>> rows){String id=UUID.randomUUID().toString(); sessions.put(id, rows); return id;}
  public List<Map<String,Object>> rows(String id){List<Map<String,Object>> r=sessions.get(id);if(r==null)throw new NoSuchElementException("Session not found. Please upload the file again.");return r;}
  public void remove(String id){sessions.remove(id);}
  public Map<String,Object> uploadResponse(String id,String filename,List<Map<String,Object>> rows){List<String> cols=columns(rows);Map<String,String> schema=new LinkedHashMap<>();for(String c:cols){Object val=null;for(Map<String,Object> r:rows)if(r.get(c)!=null&&!String.valueOf(r.get(c)).isBlank()){val=r.get(c);break;}schema.put(c,val==null?"string":val.getClass().getSimpleName().toLowerCase(Locale.ROOT));}Map<String,Long> nulls=new LinkedHashMap<>();for(String c:cols)nulls.put(c,rows.stream().filter(r->isMissing(r.get(c))).count());long duplicates=rows.size()-rows.stream().map(r->safeJson(r)).distinct().count();return Map.of("session_id",id,"filename",filename,"schema",schema,"sample_data",rows.stream().limit(10).toList(),"statistics",Map.of("total_rows",rows.size(),"total_columns",cols.size(),"null_counts",nulls,"duplicate_rows",duplicates),"message","Data uploaded. What would you like to do with it?");}
  public List<String> columns(List<Map<String,Object>> rows){LinkedHashSet<String>s=new LinkedHashSet<>();rows.forEach(r->s.addAll(r.keySet()));return new ArrayList<>(s);}
  public boolean isMissing(Object v){return v==null||NULLS.contains(String.valueOf(v).trim().toLowerCase(Locale.ROOT));}
  private String safeJson(Object o){try{return mapper.writeValueAsString(o);}catch(Exception e){return String.valueOf(o);}}
  public Map<String,Object> applyPlan(String id,String planJson) throws IOException {List<Map<String,Object>> rows=rows(id);JsonNode root=mapper.readTree(planJson);if(!root.path("operations").isArray())throw new IllegalArgumentException("Plan must contain an operations array.");List<String> log=new ArrayList<>();for(JsonNode op:root.path("operations")){String type=op.path("type").asText();String col=op.path("column").asText("");switch(type){case "remove_duplicates"->{int before=rows.size();LinkedHashMap<String,Map<String,Object>> unique=new LinkedHashMap<>();for(Map<String,Object> r:rows)unique.putIfAbsent(safeJson(r),r);rows=new ArrayList<>(unique.values());log.add("Removed "+(before-rows.size())+" duplicate rows");}case "drop_missing_rows"->{int before=rows.size();rows.removeIf(r->r.values().stream().anyMatch(this::isMissing));log.add("Removed "+(before-rows.size())+" rows with missing values");}case "fill_missing"->{String value=op.path("value").asText("");for(Map<String,Object> r:rows)for(String c:new ArrayList<>(r.keySet()))if(isMissing(r.get(c)))r.put(c,value);log.add("Filled missing values");}case "trim_whitespace"->{for(Map<String,Object> r:rows)r.replaceAll((k,v)->v instanceof String?((String)v).trim():v);log.add("Trimmed whitespace");}case "lowercase","uppercase"->{requireColumn(rows,col);for(Map<String,Object> r:rows)if(r.get(col)!=null){String v=String.valueOf(r.get(col));r.put(col,type.equals("lowercase")?v.toLowerCase(Locale.ROOT):v.toUpperCase(Locale.ROOT));}log.add(type+" applied to "+col);}case "drop_column"->{requireColumn(rows,col);rows.forEach(r->r.remove(col));log.add("Dropped column "+col);}case "rename_column"->{requireColumn(rows,col);String newName=op.path("new_name").asText("").trim();if(newName.isEmpty())throw new IllegalArgumentException("rename_column needs new_name");for(Map<String,Object> r:rows){Object v=r.remove(col);r.put(newName,v);}log.add("Renamed "+col+" to "+newName);}case "replace_value"->{requireColumn(rows,col);String from=op.path("from").asText("");String to=op.path("to").asText("");for(Map<String,Object> r:rows)if(Objects.equals(String.valueOf(r.get(col)),from))r.put(col,to);log.add("Replaced values in "+col);}default->throw new IllegalArgumentException("Unsupported operation: "+type);}}
sessions.put(id,rows);return Map.of("count",rows.size(),"total_rows",rows.size(),"columns",columns(rows),"data",rows.stream().limit(1000).toList(),"message","Cleaning completed successfully.","analysis_result",log);}
  private void requireColumn(List<Map<String,Object>> rows,String col){if(col.isBlank()||rows.stream().noneMatch(r->r.containsKey(col)))throw new IllegalArgumentException("Column not found: "+col);}
  public byte[] csvBytes(List<Map<String,Object>> rows) throws IOException {CsvMapper csv=new CsvMapper();List<String> cols=columns(rows);if(cols.isEmpty())return new byte[0];CsvSchema.Builder b=CsvSchema.builder();cols.forEach(b::addColumn);return csv.writer(b.build().withHeader()).writeValueAsBytes(rows);}
  public Map<String,Object> quickClean(List<Map<String,Object>> input){List<Map<String,Object>> out=new ArrayList<>();int processed=0;for(Map<String,Object> row:input){processed++;Map<String,Object> clean=new LinkedHashMap<>();row.forEach((k,v)->{if(!isMissing(v))clean.put(k,v instanceof String?((String)v).trim():v);});if(!clean.isEmpty())out.add(clean);}return Map.of("count",out.size(),"total_rows",input.size(),"processed",processed,"data",out.stream().limit(1000).toList());}
}
